import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useAuth } from "../../context/AuthContext";
import "../../styles/layout.css";

export default function Navbar({ onSearch }) {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const [query, setQuery] = useState("");

  const handleLogout = () => { logout(); navigate("/signin"); };

  const handleSearch = (e) => {
    setQuery(e.target.value);
    if (onSearch) onSearch(e.target.value);
  };

  // Get role from localStorage as backup if user object doesn't have it yet
  const storedUser = JSON.parse(localStorage.getItem("echo_user") || "{}");
  const role = user?.role || storedUser?.role || "user";

  return (
    <nav className="navbar">
      <Link className="nav-brand" to="/">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
          <circle cx="12" cy="12" r="10"/>
          <path d="M8 9h8M8 12h6M8 15h4"/>
        </svg>
        Echo
      </Link>

      <div className="nav-search">
        <input
          type="text"
          placeholder="Search posts..."
          value={query}
          onChange={handleSearch}
        />
      </div>

      <div className="nav-right">
        {user ? (
          <>
            <Link to="/" className="nav-link">Home</Link>
            <Link to="/saved" className="nav-link">Saved</Link>
            {(role === "admin") && (
              <Link to="/admin" className="nav-link admin-link">🛡️ Admin</Link>
            )}
            {(role === "admin" || role === "moderator") && (
              <Link to="/moderator" className="nav-link mod-link">⚡ Mod</Link>
            )}
            <Link to={`/u/${user.username}`}>
              <div className="nav-avatar" title={user.firstName}>
                {user.firstName?.[0]?.toUpperCase() || "U"}
              </div>
            </Link>
            <button className="nav-btn ghost" onClick={handleLogout}>Sign out</button>
          </>
        ) : (
          <>
            <Link to="/signin" className="nav-btn outline">Sign in</Link>
            <Link to="/signup" className="nav-btn primary">Sign up</Link>
          </>
        )}
      </div>
    </nav>
  );
}
